package io.github.aihub.chat.service;import io.github.aihub.chat.dto.*;import io.github.aihub.provider.dto.*;import io.github.aihub.provider.router.*;import org.springframework.stereotype.Service;import reactor.core.publisher.Flux;
@Service public class AIChatService{private final ModelRouter router;public AIChatService(ModelRouter r){router=r;}private ProviderChatRequest map(ChatRequest r){return new ProviderChatRequest(r.model(),r.messages().stream().map(x->new ProviderChatRequest.Message(x.role(),x.content())).toList(),r.temperature(),r.maxTokens());}public ChatResponse chat(ChatRequest r){var x=router.route(r.model()).chat(map(r));return new ChatResponse(x.provider(),x.model(),x.content(),x.finishReason());}public Flux<ChatStreamEvent> stream(ChatRequest r){return router.route(r.model()).stream(map(r)).map(x->new ChatStreamEvent(x.type(),x.provider(),x.model(),x.delta(),x.finishReason()));}}